class ModerationTest(unittest.TestCase):
    def test_legitimate_criticism_is_published(self):
        for text in LEGIT + HELD_OUT_LEGIT:
            with self.subTest(text=text):
                self.assertEqual([i.category for i in M.analyze(text, PROF)], [])

    def test_attacks_are_caught_in_the_right_category(self):
        for category, text in ATTACKS:
            with self.subTest(text=text):
                self.assertIn(category, [i.category for i in M.analyze(text, PROF)])

    def test_held_out_attacks(self):
        for text in HELD_OUT_ATTACKS:
            with self.subTest(text=text):
                self.assertNotEqual(M.decide(M.analyze(text, "Clodoveu Augusto Davis Junior")), M.PUBLISH)

    def test_common_words_never_flagged(self):
        for w in COMMON_WORDS:
            with self.subTest(word=w):
                self.assertIsNone(M.LEXICON.lookup(w))
                self.assertEqual(M.analyze(f"A aula sobre {w} foi boa e bem explicada pela professora.", PROF), [])

    def test_decisions(self):
        self.assertEqual(M.decide(M.analyze("Ele é machista: só chama os meninos para responder.", PROF)), M.HOLD)
        self.assertEqual(M.decide(M.analyze("O Renato é um palhaço, não sabe dar aula.", PROF)), M.REJECT)
        self.assertEqual(M.decide(M.analyze("Aulas boas, provas justas e listas semanais bem feitas.", PROF)), M.PUBLISH)


if __name__ == "__main__":
    unittest.main()
